// PATHS parsed into point arrays once at module load (not per-render) -
// every line has exactly 101 [x,y] points, sampled at the same 58
// lines the original SVG had. Split into the two families the grid is
// actually made of (found by checking which axis each line spans
// more of): the first 24 run mostly vertically, the remaining 34 run
// mostly horizontally.
const PARSE_D = (d) => {
  const nums = d.match(/-?\d+\.?\d*/g).map(Number);
  const points = [];
  for (let i = 0; i < nums.length; i += 2) points.push([nums[i], nums[i + 1]]);
  return points;
};
const ALL_LINES = PATHS.map(PARSE_D);
const FAMILIES = [ALL_LINES.slice(0, 24), ALL_LINES.slice(24)];

// Resamples a family of lines to `density` * its original line count.
// Below 1, this picks fewer lines; above 1, it invents new ones by
// interpolating between neighbors - either way it's really just
// "sample this family's line-index axis at N evenly spaced positions
// instead of at its original 24 (or 34) integer positions", which
// naturally reduces to the exact original lines when density is 1
// (every sampled position lands exactly on an integer index).
function resampleFamily(lines, density) {
  const targetCount = Math.max(1, Math.round(lines.length * density));
  const out = [];
  for (let j = 0; j < targetCount; j++) {
    const pos =
      targetCount === 1 ? 0 : (j * (lines.length - 1)) / (targetCount - 1);
    const i0 = Math.floor(pos);
    const i1 = Math.min(i0 + 1, lines.length - 1);
    const frac = pos - i0;
    const a = lines[i0];
    const b = lines[i1];
    out.push(a.map(([ax, ay], k) => {
      const [bx, by] = b[k];
      return [ax + (bx - ax) * frac, ay + (by - ay) * frac];
    }));
  }
  return out;
}

// Warps a line by `intensity`: 0 is the straight chord between its
// own endpoints (no warp at all), 1 is the original curve exactly,
// and anything else lerps/extrapolates between the two. Each point's
// "baseline" is where it would sit on that straight chord at the same
// fraction of the way along the line, so intensity scales exactly the
// part of each point's position that makes the line curvy in the
// first place.
function warpLine(points, intensity) {
  const [x0, y0] = points[0];
  const [x1, y1] = points[points.length - 1];
  const n = points.length - 1;
  return points.map(([x, y], i) => {
    const t = i / n;
    const bx = x0 + (x1 - x0) * t;
    const by = y0 + (y1 - y0) * t;
    return [bx + (x - bx) * intensity, by + (y - by) * intensity];
  });
}

const toPathD = (points) =>
  points
    .map(([x, y], i) => `${i === 0 ? "M" : "L"}${x.toFixed(2)},${y.toFixed(2)}`)
    .join(" ");

const WarpedGrid = ({
  gradientFrom = "#6b5ce0",
  gradientTo = "#6b5ce0",
  gradientDirection = "diagonal", // "diagonal" | "vertical" | "horizontal"
  strokeWidth = 1.4,
  strokeOpacity = 0.55,
  showBackground = false,
  backgroundColor = "#050308",

  // 1 = the original warp exactly (default). 0 = dead straight grid
  // lines (no warp at all). >1 exaggerates the same distortion further.
  intensity = 1,

  // 1 = the original 58 lines (24 + 34, default). <1 thins the grid
  // out; >1 adds interpolated lines in between the existing ones.
  density = 1,

  className = "",
}) => {
  const uid = useId();
  const gradientId = `warped-grid-stroke-${uid}`;
  const [x1, y1, x2, y2] =
    gradientDirection === "vertical"
      ? ["0%", "0%", "0%", "100%"]
      : gradientDirection === "horizontal"
      ? ["0%", "0%", "100%", "0%"]
      : ["0%", "0%", "100%", "100%"];

  const pathData = useMemo(() => {
    return FAMILIES.flatMap((family) =>
      resampleFamily(family, density).map((line) =>
        toPathD(warpLine(line, intensity))
      )
    );
  }, [intensity, density]);

  return (
    <svg
      className={className}
      viewBox="0 0 1024 1536"
      xmlns="http://www.w3.org/2000/svg"
    >
      <defs>
        <linearGradient id={gradientId} x1={x1} y1={y1} x2={x2} y2={y2}>
          <stop offset="0%" stopColor={gradientFrom} />
          <stop offset="100%" stopColor={gradientTo} />
        </linearGradient>
      </defs>

      {showBackground && (
        <rect x="0" y="0" width="1024" height="1536" fill={backgroundColor} />
      )}

      <g
        fill="none"
        stroke={`url(#${gradientId})`}
        strokeOpacity={strokeOpacity}
        strokeWidth={strokeWidth}
        strokeLinecap="round"
      >
        {pathData.map((d, i) => (
          <path key={i} d={d} />
        ))}
      </g>
    </svg>
  );
};

export default WarpedGrid;
